import{initialConfig,layout,sourcePoint,hitMask,clamp,validateProject}from'./core.mjs';
import{demoImage,render}from'./renderer.mjs';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],canvas=$('#canvas');
let image=demoImage(),config=initialConfig(),masks=[{x:.505,y:.388,rx:.165,ry:.17,scale:1,style:'ghost'}],selected=-1,tool='move',isDemo=true,fileName='veil-demo',undo=[],redo=[],drag=null,comparing=false,busy=false,generation=0,lastLayout;
function status(message){$('#status').textContent=message;}
function snapshot(){return JSON.stringify({config,masks});}
function remember(){undo.push(snapshot());if(undo.length>50)undo.shift();redo=[];syncHistory();}
function syncHistory(){$('#undo').disabled=!undo.length;$('#redo').disabled=!redo.length;}
function draw(){lastLayout=render(canvas,image,config,masks,{selected,compare:comparing});$('#output-size').textContent=`${lastLayout.w} × ${lastLayout.h} PX`;$('#selection-note').textContent=selected<0?`${masks.length} 个遮罩 · 未选中时调整全部。`:`已选中第 ${selected+1} 个遮罩 · 可单独调整。`;$('#delete-mask').disabled=selected<0;$('#image-info').textContent=isDemo?'示例角色 · 可直接体验':`${fileName} · ${image.width} × ${image.height} px`;$('#demo-badge').textContent=isDemo?'示例画布':'你的作品';$('#demo-badge').hidden=!isDemo;$('#poster-settings').hidden=config.format!=='poster';}
function syncUI(){all('[data-format]').forEach(el=>{const on=el.dataset.format===config.format;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});all('[data-scene]').forEach(el=>{const on=el.dataset.scene===config.scene;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});const style=selected>=0?masks[selected].style:config.style;all('[data-style]').forEach(el=>{const on=el.dataset.style===style;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on);});$('#title').value=config.title;$('#subtitle').value=config.subtitle;$('#ratio').value=config.ratio;const scale=Math.round((selected>=0?masks[selected].scale:masks[0]?.scale??1)*100);$('#mask-scale').value=scale;$('#scale-value').textContent=scale+'%';syncHistory();draw();}
all('[data-format]').forEach(b=>b.onclick=()=>{if(config.format===b.dataset.format)return;remember();config.format=b.dataset.format;syncUI();status(config.format==='original'?'原图遮罩模式：保留图片原始尺寸，不添加海报文字。':'海报模式：设置氛围与标题，生成角色封面。');});
all('[data-style]').forEach(b=>b.onclick=()=>{remember();config.style=b.dataset.style;if(selected>=0)masks[selected].style=config.style;else masks.forEach(m=>m.style=config.style);syncUI();status(selected>=0?'已更换所选遮罩。':'已更换全部遮罩样式。');});
all('[data-scene]').forEach(b=>b.onclick=()=>{if(config.scene===b.dataset.scene)return;remember();config.scene=b.dataset.scene;syncUI();});
for(const id of ['title','subtitle']){const el=$('#'+id);el.onfocus=()=>remember();el.oninput=()=>{config[id]=el.value;draw();};}
$('#ratio').onchange=e=>{remember();config.ratio=e.target.value;draw();};
$('#mask-scale').onpointerdown=()=>remember();$('#mask-scale').onkeydown=e=>{if(e.key.startsWith('Arrow'))remember();};$('#mask-scale').oninput=e=>{const n=Number(e.target.value)/100;if(selected>=0)masks[selected].scale=n;else masks.forEach(m=>m.scale=n);$('#scale-value').textContent=e.target.value+'%';draw();};
function changeTool(t){tool=t;all('[data-tool]').forEach(b=>{const on=b.dataset.tool===tool;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});canvas.classList.toggle('add-tool',tool==='add');$('#tool-hint').textContent=tool==='add'?'在图片区域点击添加遮罩，再切回移动工具调整。':'点击遮罩选中，拖动调整位置。';}
all('[data-tool]').forEach(b=>b.onclick=()=>changeTool(b.dataset.tool));
function point(e){const box=canvas.getBoundingClientRect();return sourcePoint({x:(e.clientX-box.left)/box.width*canvas.width,y:(e.clientY-box.top)/box.height*canvas.height},lastLayout.photo);}
canvas.onpointerdown=e=>{if(comparing)return;canvas.focus({preventScroll:true});const p=point(e);if(tool==='add'){if(p.x<0||p.y<0||p.x>1||p.y>1){status('请在图片范围内添加遮罩。');return;}if(masks.length>=100){status('最多可添加 100 个遮罩。');return;}remember();const rx=.09,ry=rx*image.width/image.height*1.2;masks.push({x:p.x,y:p.y,rx,ry,scale:1,style:config.style});selected=masks.length-1;syncUI();status('已添加遮罩。切回移动工具可以拖动它。');return;}selected=hitMask(p,masks);if(selected>=0){remember();drag={x:p.x-masks[selected].x,y:p.y-masks[selected].y};canvas.setPointerCapture(e.pointerId);}syncUI();};
canvas.onpointermove=e=>{if(!drag||selected<0)return;const p=point(e);masks[selected].x=clamp(p.x-drag.x,0,1);masks[selected].y=clamp(p.y-drag.y,0,1);draw();};
canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
function deleteSelected(){if(selected<0)return;remember();masks.splice(selected,1);selected=-1;syncUI();status('已删除选中遮罩，可以撤销。');}
$('#delete-mask').onclick=deleteSelected;
function travel(from,to){if(!from.length)return;to.push(snapshot());const state=JSON.parse(from.pop());config=state.config;masks=state.masks;selected=-1;syncUI();status(from===undo?'已撤销上一步。':'已重做上一步。');}
$('#undo').onclick=()=>travel(undo,redo);$('#redo').onclick=()=>travel(redo,undo);
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,dialog'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?travel(redo,undo):travel(undo,redo);}if(['Delete','Backspace'].includes(e.key)&&document.activeElement===canvas){e.preventDefault();deleteSelected();}if(e.key==='Escape'){selected=-1;draw();}});
const compare=$('#compare');compare.onpointerdown=e=>{comparing=true;compare.setPointerCapture(e.pointerId);draw();};compare.onpointerup=compare.onpointercancel=()=>{comparing=false;draw();};compare.onkeydown=e=>{if(e.key===' '){e.preventDefault();comparing=true;draw();}};compare.onkeyup=e=>{if(e.key===' '){comparing=false;draw();}};compare.onblur=()=>{comparing=false;draw();};
async function autoDetect(){if(busy){status('人脸定位正在进行，请稍候。');return;}if(isDemo){remember();masks=[{x:.505,y:.388,rx:.165,ry:.17,scale:1,style:config.style}];selected=-1;syncUI();status('示例角色已定位。导入真实图片后，会使用本机人脸模型识别。');return;}busy=true;const token=generation;$('#detect').disabled=true;status('首次定位需要加载本地模型，请稍候；图片不会上传。');try{const{detectFaces}=await import('./detector.mjs');const found=await detectFaces(image);if(token!==generation)return;remember();masks=found.map(m=>({...m,style:config.style}));selected=-1;syncUI();status(found.length?`已定位 ${found.length} 张人脸。可以拖动、调整大小，或手动补充。`:'未定位到人脸。动物、动漫或侧脸可能漏检，请用「补一个」手动添加。');}catch(e){console.error(e);if(token===generation)status('自动定位暂不可用。你仍可以使用「补一个」手动制作遮罩并导出。');}finally{busy=false;$('#detect').disabled=false;}}
$('#detect').onclick=autoDetect;
function imageFromURL(url){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('无法读取图片，请换一张 JPG、PNG 或 WEBP。'));img.src=url;});}
async function importImage(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status('请选择 JPG、PNG 或 WEBP 图片。');return;}if(file.size>20*1024*1024){status('图片超过 20 MB，请先缩小。');return;}const token=++generation;const url=URL.createObjectURL(file);try{const next=await imageFromURL(url);if(token!==generation)return;if(next.width*next.height>24000000){status('图片超过 2400 万像素，请先缩小。');return;}image=next;fileName=file.name.replace(/\.[^.]+$/,'').slice(0,100);isDemo=false;masks=[];selected=-1;undo=[];redo=[];syncUI();status('图片已导入，正在准备人脸定位。');if(!busy)autoDetect();else status('图片已导入。上一轮定位结束后，可以点击「自动定位人脸」。');}catch(e){status(e.message);}finally{URL.revokeObjectURL(url);}}
$('#upload').onclick=()=>$('#file').click();$('#file').onchange=e=>{importImage(e.target.files[0]);e.target.value='';};const zone=$('#dropzone');for(const name of ['dragenter','dragover'])zone.addEventListener(name,e=>{e.preventDefault();zone.classList.add('dragover');});zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('dragover');});document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');const f=[...e.dataTransfer.files].find(f=>f.type.startsWith('image/'));importImage(f);});document.addEventListener('paste',e=>{if(e.target.closest('input,textarea'))return;const item=[...e.clipboardData.items].find(i=>i.type.startsWith('image/'));if(item){e.preventDefault();importImage(item.getAsFile());}});
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
$('#export').onclick=()=>{const out=document.createElement('canvas');render(out,image,config,masks);const name=fileName.replace(/[<>:"/\\|?*\x00-\x1F]/g,'_');out.toBlob(blob=>{if(!blob){status('导出失败，请缩小图片后重试。');return;}download(blob,`${name}-幽面-${config.format==='poster'?'海报':'遮罩'}.png`);status(`PNG 已生成并交给浏览器下载：${out.width} × ${out.height} 像素。`);},'image/png');};
$('#save-project').onclick=()=>{try{const source=document.createElement('canvas');source.width=image.width;source.height=image.height;source.getContext('2d').drawImage(image,0,0);const data={kind:'veil-studio',version:1,image:source.toDataURL('image/png'),name:fileName,config,masks,demo:isDemo};if(data.image.length>33000000){status('编辑文件图片较大，请先缩小图片；PNG 导出仍可使用。');return;}download(new Blob([JSON.stringify(data)],{type:'application/json'}),'幽面-编辑文件.json');status('已生成编辑文件，包含原图与遮罩。请自行保管，之后可以重新打开。');}catch(e){status('保存失败，请重试。');}};
$('#open-project').onclick=()=>$('#project-file').click();$('#project-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>35*1024*1024){status('编辑文件超过 35 MB，无法打开。');return;}try{const project=validateProject(JSON.parse(await f.text()));const token=++generation;const next=await imageFromURL(project.image);if(token!==generation)return;if(next.width*next.height>24000000)throw new Error('图片超过 2400 万像素。');image=next;config=project.config;masks=project.masks;fileName=project.name;isDemo=project.demo;selected=-1;undo=[];redo=[];syncUI();status('编辑文件已恢复。可以继续调整遮罩和海报。');}catch(error){status(error instanceof SyntaxError?'编辑文件不是有效的 JSON。':error.message);}};
function showInfo(html){$('#dialog-content').innerHTML=html;$('#info-dialog').showModal();}
$('#help').onclick=()=>showInfo('<p class="eyebrow">QUICK START</p><h2>给面孔，另一种可能。</h2><ol><li>导入 JPG、PNG 或 WEBP。也可以拖入或粘贴图片。</li><li>自动定位支持真实人脸；动物、动漫及复杂侧脸请用「补一个」手动添加。</li><li>点击选中遮罩，拖动调整位置，使用滑块调整大小。未选中时会调整全部遮罩。</li><li>选择原图遮罩，或在海报模式里设置氛围、标题和比例。</li><li>导出无水印 PNG。保存编辑文件可在以后恢复原图与设置。</li></ol><p>快捷键：⌘/Ctrl Z 撤销；⌘/Ctrl Shift Z 重做。选中画布时，Delete 删除遮罩。</p><p>这是创作遮罩工具，不保证无法识别人物身份。编辑文件包含原图，请按你的需要保管。</p>');
$('#about').onclick=()=>showInfo('<p class="eyebrow">ABOUT VEIL STUDIO</p><h2>幽面 · 为夜晚的故事而作</h2><p>一个在浏览器中完成的角色遮罩与悬疑海报工作台。图片不上传到服务器，不需要登录。</p><p>交互流程参考作者原有的「白圈」工具；本项目的海报排版、遮罩渲染、编辑状态及文件功能为新实现。自动人脸定位使用 Google MediaPipe Tasks Vision 与 Face Landmarker，本地运行资源沿用白圈项目中已有的副本。</p><p>原创代码采用 MIT 许可。<a href="./THIRD-PARTY-NOTICES.txt" target="_blank" rel="noopener">第三方许可说明 ↗</a></p>');
$('#close-dialog').onclick=()=>$('#info-dialog').close();$('#info-dialog').onclick=e=>{if(e.target===$('#info-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
syncUI();
